// Deterministic credential recovery state manager (guidance only, no API calls)
const input = $input.first().json || {};
const userText = String(input.user_text || '').trim();

const VALID_TYPES = ['client_crm', 'trading_account', 'trading_app'];

function parseDraft(raw) {
  if (!raw) return {};
  if (typeof raw === 'object' && !Array.isArray(raw)) return { ...raw };
  if (typeof raw === 'string') {
    try {
      const parsed = JSON.parse(raw);
      if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) return { ...parsed };
    } catch (e) {}
  }
  return {};
}

function normalizeIssueType(value) {
  const v = String(value || '').trim().toLowerCase();
  if (VALID_TYPES.includes(v)) return v;
  if (v === 'client crm') return 'client_crm';
  if (v === 'trading account') return 'trading_account';
  if (v === 'trading app') return 'trading_app';
  return '';
}

function detectIssueType(textValue) {
  const text = String(textValue || '').toLowerCase();
  const credentialSignal = /(login|log in|sign in|password|passcode|credential|forgot|forget|reset|cannot access|can't access)/i.test(text);
  if (!credentialSignal) return '';
  if (/\b(client\s*crm|crm|client\s*portal|client\s*area|cabinet|portal)\b/i.test(text)) return 'client_crm';
  if (/\b(mt4|mt5|trading\s*account|investor\s*password|master\s*password|account\s*login|account\s*number|trading\s+login)\b/i.test(text)) return 'trading_account';
  if (/\b(app|mobile|desktop|webtrader|platform|application)\b/i.test(text)) return 'trading_app';
  return 'trading_app';
}

function detectPlatform(textValue) {
  const text = String(textValue || '').toLowerCase();
  if (/\bmt4\b/i.test(text)) return 'mt4';
  if (/\bmt5\b/i.test(text)) return 'mt5';
  if (/\bwebtrader\b/i.test(text)) return 'webtrader';
  if (/\bmobile\b/i.test(text)) return 'mobile';
  if (/\bdesktop\b/i.test(text)) return 'desktop';
  return '';
}

function extractLogin(textValue) {
  const text = String(textValue || '');
  const m = text.match(/(?:login|account|id|number)\s*[:#-]?\s*([A-Za-z0-9_-]{4,})/i);
  return m ? m[1] : '';
}

function detectDeliveryChannel(textValue) {
  const text = String(textValue || '').toLowerCase();
  if (/\bsms\b|\bphone\b|\bmobile\b/i.test(text)) return 'sms';
  if (/\bemail\b|\bmail\b/i.test(text)) return 'email';
  return '';
}

const draft = parseDraft(input.draft_recovery);
const issueType = normalizeIssueType(input.issue_type) || normalizeIssueType(draft.issue_type) || detectIssueType(userText);

if (!issueType) {
  return [{
    ok: true,
    collecting: true,
    issue_type: null,
    missing_fields: ['issue_type'],
    next_question: 'Please choose one so I can guide you correctly: client CRM password, trading account password (MT4/MT5), or trading app login issue.',
    resolution_steps: [],
    guide_link: null,
    offer_ticket: true,
    ticket_suggestion: 'If these steps do not solve it, I can create a support ticket for you in the next step.',
    draft_recovery: draft
  }];
}

const merged = {
  issue_type: issueType,
  platform: String(input.platform || draft.platform || detectPlatform(userText) || '').toLowerCase(),
  login: String(input.login || draft.login || extractLogin(userText) || '').trim(),
  error_message: String(input.error_message || draft.error_message || '').trim(),
  delivery_channel: String(input.delivery_channel || draft.delivery_channel || detectDeliveryChannel(userText) || '').toLowerCase()
};

if (!merged.error_message && issueType === 'trading_app' && userText.length > 0) {
  merged.error_message = userText.slice(0, 280);
}

const requiredByType = {
  client_crm: ['delivery_channel'],
  trading_account: ['platform', 'login'],
  trading_app: ['platform', 'error_message']
};

const prompts = {
  issue_type: 'Please choose: client CRM password, trading account password (MT4/MT5), or trading app login issue.',
  delivery_channel: 'Should the reset link be sent to your registered email or by SMS? Reply with email or sms.',
  platform: 'Which platform are you using? Reply with MT4, MT5, mobile, desktop, or webtrader.',
  login: 'Please share your trading account login number so I can give precise reset instructions.',
  error_message: 'Please share the exact error message shown by the app.'
};

const missing = requiredByType[issueType].filter((field) => !String(merged[field] || "").trim());

if (missing.length > 0) {
  const nextField = missing[0];
  return [{
    ok: true,
    collecting: true,
    issue_type: issueType,
    missing_fields: missing,
    next_question: prompts[nextField],
    resolution_steps: [],
    guide_link: null,
    offer_ticket: true,
    ticket_suggestion: 'If these steps do not solve it, I can create a support ticket for you in the next step.',
    draft_recovery: merged
  }];
}

const guideLinks = {
  client_crm: 'https://mycms.cmsprime.com/forgot-password',
  trading_account: 'https://mycms.cmsprime.com/help/trading-account-credentials',
  trading_app: 'https://mycms.cmsprime.com/help/trading-app-login'
};

const resolutionSteps = {
  client_crm: [
    'Open the Client CRM reset page using the guide link.',
    'Enter your registered email or phone and request a reset code.',
    'Follow the link/code received and set a new password.',
    'If you do not receive the code in 2-3 minutes, check spam and retry once.'
  ],
  trading_account: [
    'Log in to Client CRM and open your Trading Accounts section.',
    `Select your ${merged.platform.toUpperCase()} account (${merged.login}) and choose Reset/Change Password.`,
    'Set the new trading password and save changes.',
    'Use the updated credentials to log in again on the trading terminal.'
  ],
  trading_app: [
    `Confirm you are using the correct ${merged.platform.toUpperCase()} server and login details.`,
    'Update the app to the latest version and restart it.',
    'Clear cached credentials and log in again.',
    `If the error persists (${merged.error_message}), proceed with support ticket creation.`
  ]
};

return [{
  ok: true,
  collecting: false,
  issue_type: issueType,
  missing_fields: [],
  next_question: null,
  resolution_steps: resolutionSteps[issueType],
  guide_link: guideLinks[issueType],
  offer_ticket: true,
  ticket_suggestion: 'If these steps do not solve it, I can create a support ticket for you in the next step.',
  draft_recovery: merged
}];
